// Simula risposta API documenti per demo
const mockDocuments = [
  {
    id: 'doc_001',
    title: 'Machine Learning Basics',
    content: 'Machine learning is a subset of artificial intelligence that enables computers to learn from data without being explicitly programmed.',
    category: 'AI',
    language: 'en',
    source: 'internal-wiki'
  },
  {
    id: 'doc_002',
    title: 'Vector Databases',
    content: 'Vector databases store high-dimensional vectors representing embeddings of text, images, or other data types for semantic search.',
    category: 'Database',
    language: 'en',
    source: 'tech-docs'
  }
];

console.log(`📄 Generated ${mockDocuments.length} mock documents`);
return mockDocuments.map(doc => ({json: doc}));

// DEBUG: Log what we're sending
const currentDoc = $input[0].json;
console.log('📤 Processing document:', currentDoc.id);

// Prepare the payload
const payload = {
  content: currentDoc.content,
  metadata: {
    document_id: currentDoc.id,
    title: currentDoc.title,
    category: currentDoc.category,
    language: currentDoc.language,
    source: currentDoc.source || 'automated_sync',
    ingestion_time: new Date().toISOString()
  }
};

return [{ json: payload }];

// Success handler
const response = $input[0].json;
console.log('✅ Document ingested:', response.id || response.document_id);

const result = {
  status: 'SUCCESS',
  document_id: response.id || response.document_id || 'unknown',
  message: 'Document successfully ingested',
  timestamp: new Date().toISOString(),
  raw_response: response
};

return [{ json: result }];

// Error handler
const response = $input[0].json;
console.error('❌ Document ingestion failed:', response.error || response.message);

const result = {
  status: 'ERROR',
  document_id: 'unknown',
  error_message: response.error || response.message || 'Unknown error',
  timestamp: new Date().toISOString(),
  raw_response: response
};

return [{ json: result }];

// Simple logging and pass-through
const data = $input[0].json;
console.log('📝 Processed:', data.document_id || data.status);

// Just pass the data through
return [{ json: data }];

// Final summary - activated when loop is done
// This node only runs once when all documents are processed
const allItems = $input.all();
console.log('📊 FINAL SUMMARY - Total items:', allItems.length);

const successCount = allItems.filter(item => item.json.status === 'SUCCESS').length;
const errorCount = allItems.filter(item => item.json.status === 'ERROR').length;

const summary = {
  workflow: 'Automated Document Knowledge Base',
  execution_time: new Date().toISOString(),
  results: {
    total: allItems.length,
    success: successCount,
    error: errorCount,
    success_rate: allItems.length > 0 ? `${(successCount / allItems.length * 100).toFixed(1)}%` : '0%'
  },
  message: `Processed ${allItems.length} documents. Success: ${successCount}, Errors: ${errorCount}`,
  items: allItems.map(item => item.json)
};

console.log('🏁 Final summary:', JSON.stringify(summary, null, 2));
return [{ json: summary }];
